WITH kept_keys AS (SELECT id FROM employees INTERSECT ALL SELECT id FROM employees WHERE manager_id IS NOT NULL), verified AS (SELECT s.* FROM employees s INNER JOIN kept_keys k ON s.id = k.id) SELECT CASE WHEN salary >= 128000 THEN 'HIGH' ELSE 'LOW' END AS salary_tier, DATE_TRUNC('MONTH', hire_date) AS activity_month, APPROX_PERCENTILE(salary, 0.9) AS salary_p90, SIZE(COLLECT_SET(level)) AS num_levels, PERCENTILE_APPROX(salary, ARRAY(0.25, 0.5, 0.75)) AS salary_quartiles FROM verified GROUP BY CASE WHEN salary >= 128000 THEN 'HIGH' ELSE 'LOW' END, DATE_TRUNC('MONTH', hire_date) ORDER BY activity_month DESC NULLS FIRST;
